<script setup lang="ts">
import { computed, onBeforeUnmount, ref, watch } from 'vue'
import { EditorContent, useEditor } from '@tiptap/vue-3'
import { Node, mergeAttributes } from '@tiptap/core'
import StarterKit from '@tiptap/starter-kit'
import TextAlign from '@tiptap/extension-text-align'
import { ElMessage } from 'element-plus'
import { uploadFile } from '@/api/upload'
import { canonicalNoticeDocument, emptyNoticeDocument, noticeSummary, type NoticeNode } from '@/utils/noticeDocument'
import NoticeBody from './NoticeBody.vue'
const props=defineProps<{modelValue:string;disabled?:boolean}>()
const emit=defineEmits<{'update:modelValue':[value:string];summary:[value:{text:string;images:string[]}];busy:[value:boolean]}>()
const preview=ref(false),uploading=ref(false),fileInput=ref<HTMLInputElement|null>(null),selectionVersion=ref(0)
let replacing=false
const ImageNode=Node.create({name:'image',group:'block',atom:true,draggable:true,addAttributes(){return {src:{default:''},alt:{default:''},widthPercent:{default:100},textAlign:{default:'left'}}},parseHTML(){return [{tag:'img[src]',getAttrs:el=>({src:el.getAttribute('src'),alt:el.getAttribute('alt')??'',widthPercent:100,textAlign:'left'})}]},renderHTML({HTMLAttributes}){const a=HTMLAttributes;return ['img',mergeAttributes({src:a.src,alt:a.alt,'data-notice-image':'true',style:`display:block;width:${a.widthPercent}%;height:auto;margin-left:${a.textAlign==='center'?'auto':a.textAlign==='right'?'auto':'0'};margin-right:${a.textAlign==='center'?'auto':'0'}`})]}})
function read(value:string){try{return JSON.parse(value)}catch{return emptyNoticeDocument()}}
function changed(){if(!editor.value)return;const doc=canonicalNoticeDocument(editor.value.getJSON() as NoticeNode);const json=JSON.stringify(doc);emit('update:modelValue',json);emit('summary',noticeSummary(doc));selectionVersion.value++}
const editor=useEditor({editable:!props.disabled,extensions:[StarterKit.configure({heading:{levels:[2]},blockquote:false,code:false,codeBlock:false,strike:false,horizontalRule:false,italic:false,underline:false,link:false}),TextAlign.configure({types:['heading','paragraph'],alignments:['left','center','right']}),ImageNode],content:read(props.modelValue),editorProps:{attributes:{class:'notice-editor-canvas',role:'textbox','aria-label':'公告正文编辑器','aria-multiline':'true'},transformPastedHTML(html){const d=new DOMParser().parseFromString(html,'text/html');d.querySelectorAll('img').forEach(img=>{if(!/^\/uploads\/[A-Za-z0-9_./-]+$/.test(img.getAttribute('src')??''))img.remove()});return d.body.innerHTML}},onUpdate:changed,onSelectionUpdate(){selectionVersion.value++}})
const imageAttrs=computed(()=>{void selectionVersion.value;return editor.value?.isActive('image')?editor.value.getAttributes('image'):null})
const summary=computed(()=>{try{return noticeSummary(read(props.modelValue))}catch{return {text:'',images:[]}}})
watch(()=>props.modelValue,value=>{if(editor.value&&JSON.stringify(canonicalNoticeDocument(editor.value.getJSON() as NoticeNode))!==value)editor.value.commands.setContent(read(value),{emitUpdate:false})})
watch(()=>[props.disabled,uploading.value],()=>editor.value?.setEditable(!props.disabled&&!uploading.value),{immediate:true})
function align(value:'left'|'center'|'right'){if(imageAttrs.value)editor.value?.chain().focus().updateAttributes('image',{textAlign:value}).run();else editor.value?.chain().focus().setTextAlign(value).run();selectionVersion.value++}
function resize(value:number){editor.value?.chain().focus().updateAttributes('image',{widthPercent:value}).run();selectionVersion.value++}
function pick(replace=false){if(props.disabled||uploading.value)return;if(!replace&&summary.value.images.length>=6){ElMessage.warning('正文最多6张图片');return}replacing=replace;fileInput.value?.click()}
async function upload(event:Event){const input=event.target as HTMLInputElement,file=input.files?.[0];input.value='';if(!file||!editor.value)return;if(file.size>5*1024*1024||!/\.(jpe?g|png|gif)$/i.test(file.name)){ElMessage.error('请选择5MB以内的JPG/PNG/GIF图片');return}uploading.value=true;emit('busy',true);try{const result=await uploadFile(file,'IMAGE');if(replacing&&editor.value.isActive('image'))editor.value.chain().focus().updateAttributes('image',{src:result.fileUrl}).run();else editor.value.chain().focus().insertContent({type:'image',attrs:{src:result.fileUrl,alt:'',widthPercent:100,textAlign:'left'}}).run();changed()}catch(e){ElMessage.error(e instanceof Error?e.message:'插图失败，请重试')}finally{uploading.value=false;emit('busy',false)}}
onBeforeUnmount(()=>editor.value?.destroy())
</script>
<template><section class="notice-editor" :class="{'is-preview':preview}">
 <div class="editor-toolbar" role="toolbar" aria-label="公告排版"><div class="tool-group">
  <button type="button" :disabled="disabled||uploading" :aria-pressed="editor?.isActive('bold')" @click="editor?.chain().focus().toggleBold().run()"><strong>加粗</strong></button>
  <button type="button" :disabled="disabled||uploading" @click="editor?.chain().focus().setParagraph().run()">正文</button>
  <button type="button" :disabled="disabled||uploading" @click="editor?.chain().focus().toggleHeading({level:2}).run()">二级标题</button>
 </div><div class="tool-group"><button type="button" :disabled="disabled||uploading" @click="align('left')">左对齐</button><button type="button" :disabled="disabled||uploading" @click="align('center')">居中</button><button type="button" :disabled="disabled||uploading" @click="align('right')">右对齐</button></div>
 <div class="tool-group"><button type="button" :disabled="disabled||uploading" @click="editor?.chain().focus().toggleBulletList().run()">无序列表</button><button type="button" :disabled="disabled||uploading" @click="editor?.chain().focus().toggleOrderedList().run()">有序列表</button></div>
 <div class="tool-group"><button type="button" :disabled="disabled||uploading" @click="pick()">{{uploading?'图片上传中…':'插入本地图片'}}</button><button type="button" :disabled="disabled||uploading||!editor?.can().undo()" @click="editor?.chain().focus().undo().run()">撤销</button><button type="button" :disabled="disabled||uploading||!editor?.can().redo()" @click="editor?.chain().focus().redo().run()">重做</button></div>
 <button type="button" class="preview-toggle" :aria-pressed="preview" @click="preview=!preview">{{preview?'继续写作':'预览正文'}}</button>
 </div>
 <div v-if="imageAttrs&&!preview" class="image-controls"><span>选中图片</span><label>宽度<select :disabled="disabled||uploading" :value="imageAttrs.widthPercent" aria-label="图片宽度比例" @change="resize(Number(($event.target as HTMLSelectElement).value))"><option v-for="width in [25,50,75,100]" :key="width" :value="width">{{width}}%</option></select></label><input type="range" min="25" max="100" :value="imageAttrs.widthPercent" aria-label="拖动调整图片宽度" :disabled="disabled||uploading" @input="resize(Number(($event.target as HTMLInputElement).value))"/><label>图片说明<input :value="imageAttrs.alt" maxlength="200" :disabled="disabled||uploading" @input="editor?.chain().focus().updateAttributes('image',{alt:($event.target as HTMLInputElement).value}).run()"/></label><button type="button" :disabled="disabled||uploading" @click="pick(true)">替换图片</button><button type="button" :disabled="disabled||uploading" @click="editor?.chain().focus().deleteSelection().run()">移除图片</button></div>
 <div class="document-sheet"><NoticeBody v-if="preview" :body-json="modelValue"/><EditorContent v-show="!preview" :editor="editor"/><p v-if="!preview&&!summary.text&&!summary.images.length" class="canvas-placeholder">在这里撰写公告。选中文字进行排版，或插入本地图片。</p></div>
 <footer class="editor-foot"><span>更改仅在保存后公开</span><span>{{summary.text.length}} / 5000 字 · {{summary.images.length}} / 6 张图片</span></footer>
 <input ref="fileInput" type="file" hidden accept=".jpg,.jpeg,.png,.gif" aria-label="选择公告图片" @change="upload"/>
</section></template>
<style scoped>
.notice-editor{width:100%;border:1px solid #dce4ef;border-radius:8px;overflow:hidden;background:#f6f8fb}.editor-toolbar{position:sticky;top:0;z-index:2;display:flex;flex-wrap:wrap;gap:6px;padding:10px;border-bottom:1px solid #dce4ef;background:#fff}.tool-group{display:flex;gap:2px;padding-right:6px;border-right:1px solid #dce4ef}.editor-toolbar button,.image-controls button{font:inherit;font-size:12px;border:0;border-radius:4px;background:transparent;padding:7px;color:#34465f;cursor:pointer}.editor-toolbar button:hover,.editor-toolbar button[aria-pressed=true]{background:#eaf0ff;color:#2454ce}.editor-toolbar button:disabled{opacity:.45;cursor:not-allowed}.editor-toolbar button:focus-visible,.image-controls input:focus-visible{outline:2px solid #386aff;outline-offset:2px}.preview-toggle{margin-left:auto}.document-sheet{position:relative;max-width:780px;min-height:400px;padding:36px 40px;margin:22px auto;background:#fff;border:1px solid #e4e9f0;box-sizing:border-box}.document-sheet :deep(.notice-editor-canvas){outline:0;min-height:320px;line-height:1.9;overflow-wrap:anywhere;color:#12263f}.document-sheet :deep(.notice-editor-canvas p){margin:0 0 1em}.document-sheet :deep(.notice-editor-canvas img){max-width:100%;border-radius:4px}.document-sheet :deep(.ProseMirror-selectednode){outline:2px solid #386aff;outline-offset:3px}.canvas-placeholder{pointer-events:none;position:absolute;top:36px;left:40px;right:40px;margin:0;color:#909dad;font-size:14px;line-height:1.9}.editor-foot{display:flex;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:10px 16px;font-size:12px;color:#677890;border-top:1px solid #dce4ef}.image-controls{display:flex;align-items:center;flex-wrap:wrap;gap:12px;padding:10px 14px;background:#edf3ff;font-size:12px}.image-controls label{display:flex;align-items:center;gap:5px}.image-controls input{max-width:180px}.image-controls select{border:1px solid #b9c7dd;padding:4px;border-radius:4px}@media(max-width:700px){.document-sheet{padding:22px 18px;margin:10px;min-height:360px}.canvas-placeholder{top:22px;left:18px;right:18px}.tool-group{border:0}.editor-toolbar{position:static;gap:2px}}
</style>
